  [402000] = { "Riduce il tempo di recupero del tuo incantesimo ⟦Power Word: Shield=Parola del Potere: Scudo⟧ di $D1 e ne riduce il costo in mana del $N2%.", nil, 0x91cc52b2, nil, "um" },
  [402004] = { "Riduce istantaneamente del $N1% tutti i danni subiti da un bersaglio amico e ne aumenta del $N2% la resistenza agli effetti di dissoluzione per $D1.", "Tutti i danni subiti ridotti del $N1% e resistenza agli effetti di dissoluzione aumentata del $N2%.", 0xf134f0eb, 0x2ab9e2e5, "uu" },
