  [402368] = { nil, "Danni magici inflitti aumentati del $N1%.", nil, 0xb9096e71, "mu" },
  [402668] = { "Applica il tuo talento ⟦Vampiric Embrace=Abbraccio Vampirico⟧ al bersaglio, gli infligge $N1 danni da ombra in $D1 e fa ottenere a tutti i membri del gruppo mana pari al $N3% dei danni degli incantesimi d'ombra che infliggi al bersaglio.", "$N1 danni da ombra ogni $N2 s. Il gruppo del Sacerdote ottiene mana pari al $N3% dei danni degli incantesimi d'ombra inflitti dal Sacerdote a questo bersaglio.", 0x0fe3e73d, 0x3bf17666, "uu" },
  [402686] = { nil, "Questa creatura è stata trasformata.", nil, 0xf5cbc9b2, "mu" },
  [402779] = { "Il $N1% dei danni da incantesimi d'ombra subiti rigenera mana per il gruppo del Sacerdote.", nil, 0xf0e2b1af, nil, "um" },
  [402789] = { "Richiama un occhio del Vuoto che combatte per te per $D1. L'occhio può lanciare diverse maledizioni sul tuo bersaglio.", nil, 0x305d9a60, nil, "um" },
  [402790] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [402791] = { "Maledice il bersaglio per $D1, riducendone le resistenze all'ombra e all'arcano di $N2 e aumentando del $N3% i danni da ombra e da arcano che subisce. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Resistenze all'ombra e all'arcano ridotte di $N1. Danni da ombra e da arcano subiti aumentati del $N2%.", 0xd622ece7, 0xa6c9f31f, "uu" },
  [402792] = { "Maledice il bersaglio per $D1, riducendone le resistenze al fuoco e al gelo di $N2 e aumentando del $N3% i danni da fuoco e da gelo che subisce. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Riduce le resistenze al fuoco e al gelo di $N1. Aumenta del $N2% i danni da fuoco e da gelo subiti.", 0xfe48135a, 0x4abb0038, "uu" },
  [402794] = { "Costringe il bersaglio a parlare in lingua demoniaca, rallentando del $N1% il tempo di lancio di tutti gli incantesimi. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta. Dura $D1.", "Parla in lingua demoniaca: tempo di lancio aumentato del $N1%.", 0x26665dfe, 0xa89ef244, "uu" },
  [402799] = { "Stacca frammenti della tua anima per animare $N1 copie in miniatura di te che tentano di attaccare il tuo bersaglio attuale con una mazza, una spada e un'ascia, riducendo rispettivamente la velocità d'attacco, la potenza d'attacco e l'Armatura di qualsiasi bersaglio colpiscano.", nil, 0x15c256c1, nil, "um" },
  [402801] = { "Anima $N1 scheletri che attaccano il tuo bersaglio attuale con una mazza, una spada e un'ascia, riducendo rispettivamente la velocità d'attacco, la potenza d'attacco e l'Armatura del bersaglio.", nil, 0xf7b13019, nil, "um" },
  [402802] = { "Anima $N1 scheletri che attaccano il tuo bersaglio attuale con una mazza, una spada e un'ascia, riducendo rispettivamente la velocità d'attacco, la potenza d'attacco e l'Armatura del bersaglio.", nil, 0xf7b13019, nil, "um" },
  [402808] = { "Aumenta del $N1% l'intervallo tra gli attacchi di un nemico. Dura $D1.", "Intervallo tra gli attacchi aumentato del $N1%.", 0x2c4ab1cd, 0x4f44ab25, "uu" },
  [402811] = { "Riduce la potenza d'attacco del bersaglio di $N1. Dura $D1.", "Potenza d'attacco ridotta di $N1.", 0x915e951a, 0xe8e28594, "uu" },
  [402818] = { "Riduce l'Armatura di un nemico di $N1. Dura $D1.", "Armatura ridotta di $N1.", 0x332347c0, 0x57b604c7, "uu" },
  [402832] = { "Ottieni l'abilità Preghiera di Guarigione:\n\n$I1\nPone sul bersaglio un incantesimo che lo cura di $N1 la prossima volta che subisce danni o riceve una cura non periodica. Quando avviene la cura, Preghiera di Guarigione salta su un membro del gruppo o dell'incursione entro $N2 m. Salta fino a $N3 volte e dura $D1 dopo ogni salto. Questo incantesimo può essere posto su un solo bersaglio alla volta per incantatore.", nil, 0x90fb0eff, nil, "um" },
  [402833] = { "Ottieni l'abilità Parola d'Ombra: Morte:\n\n$I1\nUna parola di oscuro vincolo che infligge $N1 danni da ombra al bersaglio. Se il bersaglio non viene ucciso da Parola d'Ombra: Morte, l'incantatore subisce danni pari al $N2% dei danni tentati contro il bersaglio.", nil, 0x45a66e95, nil, "um" },
  [402834] = { "Ottieni l'abilità Protezione dell'Anima:\n\n$I1\nRiduce il tempo di recupero del tuo incantesimo Parola del Potere: Scudo di $D1 e ne riduce il costo in mana del $N2%.", nil, 0x51131f6a, nil, "um" },
  [402836] = { "Ottieni l'abilità Homunculi:\n\n$I1\nStacca frammenti della tua anima per animare $N1 copie in miniatura di te che tentano di attaccare il tuo bersaglio attuale con una mazza, una spada e un'ascia, riducendo rispettivamente la velocità d'attacco, la potenza d'attacco e l'Armatura di qualsiasi bersaglio colpiscano.", nil, 0xb55934a5, nil, "um" },
  [402837] = { "Ottieni l'abilità Cura Combinata:\n\n$I1\nCura un bersaglio amico e l'incantatore di $N1. Minaccia ridotta.", nil, 0xcfddc68b, nil, "um" },
  [402838] = { "Ottieni l'abilità Pena Condivisa:\n\n$I1\nLa tua Parola d'Ombra: Dolore ora colpisce anche fino a $N1 bersagli aggiuntivi vicini entro $N2 m.", nil, 0x0264c853, nil, "um" },
  [402839] = { "Ottieni l'abilità Soppressione del Dolore:\n\n$I1\nRiduce istantaneamente del $N1% tutti i danni subiti da un bersaglio amico e ne aumenta del $N2% la resistenza agli effetti di dissoluzione per $D1.", nil, 0xb5d5e294, nil, "um" },
  [402841] = { "Ottieni l'abilità Tocco Vampirico:\n\n$I1\nApplica il tuo talento Abbraccio Vampirico al bersaglio, gli infligge $N1 danni da ombra in $D1 e fa ottenere a tutti i membri del gruppo mana pari al $N3% dei danni degli incantesimi d'ombra che infliggi al bersaglio.", nil, 0x4079090c, nil, "um" },
  [402842] = { "Ottieni l'abilità Circolo di Guarigione:\n\n$I1\nCura di $N2 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui.", nil, 0x0e8241db, nil, "um" },
  [402843] = { "Ottieni l'abilità Spirito d'Ombra:\n\n$I1\nCrea uno spirito d'ombra che attacca il bersaglio. L'incantatore riceve il $N1% di mana quando lo Spirito d'Ombra attacca. Dura $D1.", nil, 0x893e0778, nil, "um" },
  [402844] = { "Ottieni l'abilità Contrizione:\n\n$I1\nScaglia una raffica di luce sacra sul bersaglio, infliggendo $N1 danni da sacro a un nemico o curando un alleato di $N2, all'istante e poi ogni $D1 per $D2.", nil, 0x25dfc3da, nil, "um" },
  [402846] = { "Ottieni l'abilità Eye of the Void:\n\n$I1\nRichiama un occhio del Vuoto che combatte per te per $D1. L'occhio può lanciare diverse maledizioni sul tuo bersaglio.", nil, 0xf311e4df, nil, "um" },
