  [402855] = { "Incidi sui tuoi stivali la runa Soppressione del Dolore:\n\n$I1\nRiduce istantaneamente del $N1% tutti i danni subiti da un bersaglio amico e ne aumenta del $N2% la resistenza agli effetti di dissoluzione per $D1.", nil, 0xb2fd4d86, nil, "um" },
  [402857] = { "Incidi sul tuo mantello la runa Tocco Vampirico:\n\n$I1\nApplica il tuo talento Abbraccio Vampirico al bersaglio, gli infligge $N1 danni da ombra in $D1 e fa ottenere a tutti i membri del gruppo mana pari al $N3% dei danni degli incantesimi d'ombra che infliggi al bersaglio.", nil, 0x8340998c, nil, "um" },
